#include <WiFi.h>
#include <Network.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// =====================================================
// ESP32-S3 WIFI EXTENDER
// =====================================================

// ---------- YOUR MAIN ROUTER ----------
const char* ROUTER_SSID = "Cgates_2650";
const char* ROUTER_PASSWORD = "PUT_YOUR_ROUTER_PASSWORD_HERE";

// ---------- WIFI CREATED BY ESP ----------
const char* EXTENDER_SSID = "wifi";
const char* EXTENDER_PASSWORD = "esp32wifi";

// ---------- OLED ----------
#define OLED_WIDTH 128
#define OLED_HEIGHT 64

#define OLED_SDA 8
#define OLED_SCL 9

Adafruit_SSD1306 display(
  OLED_WIDTH,
  OLED_HEIGHT,
  &Wire,
  -1
);

// ---------- AP NETWORK ----------
IPAddress apIP(192, 168, 50, 1);
IPAddress apGateway(192, 168, 50, 1);
IPAddress apSubnet(255, 255, 255, 0);

bool wifiConnected = false;
bool natEnabled = false;

void oledMessage(String line1, String line2 = "", String line3 = "") {
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);

  display.setCursor(0, 0);
  display.println(line1);

  display.setCursor(0, 18);
  display.println(line2);

  display.setCursor(0, 36);
  display.println(line3);

  display.display();
}

void setup() {

  Serial.begin(115200);
  delay(1000);

  // ===================================================
  // OLED
  // ===================================================

  Wire.begin(OLED_SDA, OLED_SCL);

  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED not found.");
  } else {
    oledMessage(
      "ESP32 WIFI EXTENDER",
      "Starting..."
    );
  }

  // ===================================================
  // NETWORK MANAGER
  // ===================================================

  Network.begin();

  // ===================================================
  // START ACCESS POINT
  // ===================================================

  WiFi.AP.begin();

  WiFi.AP.config(
    apIP,
    apGateway,
    apSubnet
  );

  if (!WiFi.AP.create(
        EXTENDER_SSID,
        EXTENDER_PASSWORD
      )) {

    Serial.println("Failed to start AP!");

    oledMessage(
      "AP ERROR",
      "Could not start",
      "WiFi"
    );

    while (true) {
      delay(1000);
    }
  }

  Serial.println();
  Serial.println("==============================");
  Serial.println("ESP32 EXTENDER AP STARTED");
  Serial.println("==============================");

  Serial.print("SSID: ");
  Serial.println(EXTENDER_SSID);

  Serial.print("Password: ");
  Serial.println(EXTENDER_PASSWORD);

  Serial.print("AP IP: ");
  Serial.println(WiFi.AP.localIP());

  // ===================================================
  // CONNECT TO MAIN ROUTER
  // ===================================================

  WiFi.STA.begin();

  Serial.println();
  Serial.print("Connecting to: ");
  Serial.println(ROUTER_SSID);

  WiFi.STA.connect(
    ROUTER_SSID,
    ROUTER_PASSWORD
  );

  oledMessage(
    "Connecting...",
    ROUTER_SSID
  );

  // Wait up to 30 seconds

  unsigned long startTime = millis();

  while (
    !WiFi.STA.hasIP() &&
    millis() - startTime < 30000
  ) {

    Serial.print(".");

    delay(500);
  }

  Serial.println();

  // ===================================================
  // CONNECTION RESULT
  // ===================================================

  if (!WiFi.STA.hasIP()) {

    Serial.println("FAILED TO CONNECT.");

    oledMessage(
      "WIFI ERROR",
      "Router not found",
      ROUTER_SSID
    );

    // Keep AP running so you can still connect
    while (true) {

      delay(1000);

    }
  }

  wifiConnected = true;

  Serial.println();
  Serial.println("==============================");
  Serial.println("CONNECTED TO ROUTER");
  Serial.println("==============================");

  Serial.print("Router IP: ");
  Serial.println(WiFi.STA.localIP());

  Serial.print("Gateway: ");
  Serial.println(WiFi.STA.gatewayIP());

  Serial.print("Signal: ");
  Serial.print(WiFi.STA.RSSI());
  Serial.println(" dBm");

  // ===================================================
  // ENABLE NAT
  // ===================================================

  Serial.println();
  Serial.println("Enabling NAT...");

  natEnabled = WiFi.AP.enableNAPT(true);

  if (natEnabled) {

    Serial.println("NAT ENABLED!");

    Serial.println();
    Serial.println("==============================");
    Serial.println("EXTENDER READY");
    Serial.println("==============================");

    Serial.print("Connect to: ");
    Serial.println(EXTENDER_SSID);

    Serial.print("Password: ");
    Serial.println(EXTENDER_PASSWORD);

    Serial.println();
    Serial.println("Internet should now be");
    Serial.println("available through the ESP32.");

    oledMessage(
      "EXTENDER READY",
      "SSID: wifi",
      "Signal: " + String(WiFi.STA.RSSI()) + " dBm"
    );

  } else {

    Serial.println("NAT FAILED!");

    oledMessage(
      "NAT ERROR",
      "AP is running",
      "Internet unavailable"
    );
  }
}

// =====================================================
// MAIN LOOP
// =====================================================

void loop() {

  static unsigned long lastUpdate = 0;

  if (millis() - lastUpdate >= 3000) {

    lastUpdate = millis();

    // -----------------------------------------------
    // If router disconnected, try reconnecting
    // -----------------------------------------------

    if (!WiFi.STA.hasIP()) {

      wifiConnected = false;

      Serial.println("Router disconnected.");
      Serial.println("Trying to reconnect...");

      oledMessage(
        "RECONNECTING...",
        ROUTER_SSID
      );

      WiFi.STA.connect(
        ROUTER_SSID,
        ROUTER_PASSWORD
      );

      return;
    }

    // -----------------------------------------------
    // Current signal
    // -----------------------------------------------

    int signal = WiFi.STA.RSSI();

    // -----------------------------------------------
    // Connected clients
    // -----------------------------------------------

    uint8_t clients = WiFi.AP.stationCount();

    // -----------------------------------------------
    // Serial information
    // -----------------------------------------------

    Serial.println();
    Serial.println("------------------------------");

    Serial.print("Router signal: ");
    Serial.print(signal);
    Serial.println(" dBm");

    Serial.print("Extender clients: ");
    Serial.println(clients);

    Serial.print("Router IP: ");
    Serial.println(WiFi.STA.localIP());

    Serial.print("Extender IP: ");
    Serial.println(WiFi.AP.localIP());

    // -----------------------------------------------
    // OLED
    // -----------------------------------------------

    display.clearDisplay();

    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);

    display.setCursor(0, 0);
    display.println("WIFI EXTENDER");

    display.setCursor(0, 14);
    display.println("AP: wifi");

    display.setCursor(0, 28);
    display.print("Signal: ");
    display.print(signal);
    display.println(" dBm");

    display.setCursor(0, 42);
    display.print("Clients: ");
    display.println(clients);

    display.setCursor(0, 56);

    if (natEnabled) {
      display.println("NAT: ON");
    } else {
      display.println("NAT: OFF");
    }

    display.display();
  }
}
